/// Enable gui controls (global state)
pub fn enable() void {
    c.GuiEnable();
}

/// Disable gui controls (global state)
pub fn disable() void {
    c.GuiDisable();
}

/// Lock gui controls (global state)
pub fn lock() void {
    c.GuiLock();
}

/// Unlock gui controls (global state)
pub fn unlock() void {
    c.GuiUnlock();
}

/// Check if gui is locked (global state)
pub fn isLocked() bool {
    return c.GuiIsLocked();
}

/// Set gui controls alpha (global state), alpha goes from 0.0f to 1.0f
pub fn setAlpha(alpha: f32) void {
    c.GuiSetAlpha(alpha);
}

/// Set gui state (global state)
pub fn setState(state: State) void {
    c.GuiSetState(@backingInt(state));
}

/// Get gui state (global state)
pub fn getState() State {
    return @fromBackingInt(@intCast(c.GuiGetState()));
}

/// Set gui custom font (global state)
pub fn setFont(font: Font) void {
    c.GuiSetFont(font);
}

/// Get gui custom font (global state)
pub fn getFont() Font {
    return c.GuiGetFont();
}

/// Set one style property
pub fn setStyle(control: Control, property: anytype, value: i32) void {
    c.GuiSetStyle(@backingInt(control), propertyValue(property), value);
}

/// Get one style property
pub fn getStyle(control: Control, property: anytype) i32 {
    return c.GuiGetStyle(@backingInt(control), propertyValue(property));
}

/// Load style file over global style variable (.rgs)
pub fn loadStyle(fileName: ?[:0]const u8) void {
    c.GuiLoadStyle(if (fileName) |s| s.ptr else null);
}

/// Load style from memory (binary only)
pub fn loadStyleFromMemory(fileData: []const u8) void {
    c.GuiLoadStyleFromMemory(fileData.ptr, @intCast(fileData.len));
}

/// Load style default over global style
pub fn loadStyleDefault() void {
    c.GuiLoadStyleDefault();
}

/// Enable gui tooltips (global state)
pub fn enableTooltip() void {
    c.GuiEnableTooltip();
}

/// Disable gui tooltips (global state)
pub fn disableTooltip() void {
    c.GuiDisableTooltip();
}

/// Set tooltip string
pub fn setTooltip(tooltip: ?[:0]const u8) void {
    c.GuiSetTooltip(if (tooltip) |s| s.ptr else null);
}

/// Get text with icon id prepended (if supported)
pub fn iconText(iconId: IconName, text: ?[:0]const u8) [:0]const u8 {
    return std.mem.span(c.GuiIconText(@backingInt(iconId), if (text) |s| s.ptr else null));
}

/// Set default icon drawing size
pub fn setIconScale(scale: i32) void {
    c.GuiSetIconScale(scale);
}

/// Get raygui icons data pointer
pub fn getIcons() [*]u32 {
    return c.GuiGetIcons();
}

/// Load raygui icons file (.rgi) into internal icons data
pub fn loadIcons(fileName: ?[:0]const u8, loadIconsName: bool) ?[*][*:0]u8 {
    return @ptrCast(c.GuiLoadIcons(if (fileName) |s| s.ptr else null, loadIconsName));
}

/// Load raygui icons file (.rgi) from memory into internal icons data
pub fn loadIconsFromMemory(fileData: []const u8, loadIconsName: bool) ?[*][*:0]u8 {
    return @ptrCast(c.GuiLoadIconsFromMemory(fileData.ptr, @intCast(fileData.len), loadIconsName));
}

